css:
/* From Uiverse.io by yaroslavas2001 - Tags: card */
.__UIV_SCOPE__ .card {
  padding: 20px 10px;
  border-radius: 10%;
  height: 280px;
  width: 250px;
  display: flex;
  flex-direction: column;
  align-items: center;
  color: white;
}

.__UIV_SCOPE__ .card::before,
.__UIV_SCOPE__ .card::after {
  content: '';
  position: absolute;
  z-index: -1;
  filter: blur(29px);
  border-radius: 50%;
}

.__UIV_SCOPE__ .card::before {
  border: 30px dashed #2061c2;
  width: 200px;
  height: 250px;
  bottom: 90px;
  animation: 11s linear 0s normal none infinite running borderBefore;
}

.__UIV_SCOPE__ .card::after {
  border: 30px dashed #9238BD;
  width: 250px;
  height: 200px;
  animation: 9s linear 0s normal none infinite running borderAfter;
}

.__UIV_SCOPE__ .heading {
  font-weight: bold;
  text-align: center;
  color: #F2F2F2;
}

.__UIV_SCOPE__ .heading span {
  letter-spacing: 4px;
  line-height: 25px;
}

.__UIV_SCOPE__ .content {
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
  padding: 10px;
  position: relative;
}

.__UIV_SCOPE__ .content::before {
  content: '';
  font-size: 15px;
  position: absolute;
  filter: blur(19px);
  border-radius: 50%;
  border: 15px dashed #6f21a3;
  width: 100px;
  height: 150px;
  top: 0px;
  left: 50px;
  z-index: -1;
  animation: 11s linear 0s normal none infinite running borderAfter;
}

@keyframes borderBefore {
  0% {
    transform: rotate(360deg);
  }

  100% {
    transform: rotate(0deg);
  }
}

@keyframes borderAfter {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}

.__UIV_SCOPE__ .item {
  height: 100%;
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  cursor: pointer;
}

.__UIV_SCOPE__ .item svg {
  margin-right: 10px;
}

.__UIV_SCOPE__ .item {
  position: relative;
  transition: opacity .5s ease-out;
}

.__UIV_SCOPE__ .item:hover {
  font-weight: bold;
}

.__UIV_SCOPE__ .item::before,
.__UIV_SCOPE__ .item::after {
  opacity: 0;
  width: 5px;
  height: 5px;
  border-radius: 20px;
  position: absolute;
  background: rgba(255, 255, 255, 0.3);
  box-shadow: 10px 10px 17px 20px  rgba(255, 255, 255, 0.3);
  transition: opacity .5s ease-out;
  animation: 8s linear 0s normal none infinite running item;
}

@keyframes item {
  0% {
    transform: translateX(0px) translateY(0px);
  }

  25% {
    transform: translateX(5px) translateY(-10px);
  }

  50% {
    transform: translateX(10px) translateY(10px);
  }

  75% {
    transform: translateX(5px) translateY(-10px);
  }

  100% {
    transform: translateX(0px) translateY(0px);
  }
}

.__UIV_SCOPE__ .item::before {
  left: 0px;
  top: 10px;
}

.__UIV_SCOPE__ .item::after {
  right: 30px;
  top: 10px;
}

.__UIV_SCOPE__ .item--create::before {
  content: '💻';
}

.__UIV_SCOPE__ .item--create:hover::before {
  opacity: 1;
}

.__UIV_SCOPE__ .item--create:after {
  content: '📈';
}

.__UIV_SCOPE__ .item--create:hover:after {
  opacity: 1;
}

.__UIV_SCOPE__ .item--post::before {
  content: '🌌';
}

.__UIV_SCOPE__ .item--post:hover::before {
  opacity: 1;
}

.__UIV_SCOPE__ .item--post:after {
  content: '🎆';
}

.__UIV_SCOPE__ .item--post:hover:after {
  opacity: 1;
}

.__UIV_SCOPE__ .item--inspire::before {
  content: '✨';
}

.__UIV_SCOPE__ .item--inspire:hover::before {
  opacity: 1;
}

.__UIV_SCOPE__ .item--inspire:after {
  content: '🌊';
}

.__UIV_SCOPE__ .item--inspire:hover:after {
  opacity: 1;
}

.__UIV_SCOPE__ button {
  background: transparent;
  border: 0px;
  border-radius: 20px;
  padding: 10px 30px;
  color: #fff;
  font-weight: bold;
  cursor: pointer;
  position: relative;
  animation: 0.9s linear 0s normal none infinite running button;
  transition: all .5s ease-out;
}

.__UIV_SCOPE__ button:hover {
  letter-spacing: 1px;
}

@keyframes button {
  0% {
    border: 2px dotted rgba(73, 53, 247, 0.9);
  }

  100% {
    border: 2px dashed rgba(120, 12, 243,0.9);
  }
}
